async function retry(task, attempts = 3, delay = 500) {
  for (let i = 1; i <= attempts; i++) {
    try { return await task(); }
    catch (err) {
      if (i === attempts) throw err;
      await sleep(delay * 2 ** (i - 1));
    }
  }
}

